    /**
     * Tests getting all IdentityDocuments.
     *
     * @return    Collection
     */
    public List<IdentityDocument> testGetAll() throws Throwable {
    LOGGER.info( "IdentityDocumentTest:testGetAll() - Retrieving Collection of IdentityDocuments:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all IdentityDocument : " );
    List<IdentityDocument> collection  = null;

    try {
        // call the static get method on the IdentityDocumentService
        collection = service.getAllIdentityDocument();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            IdentityDocument currEntity  = null;
            Iterator<IdentityDocument> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getIdentityDocumentId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

